/* =========================================================
   Pixel Reveal Image Effect
   Requires: GSAP + ScrollTrigger
   Author: YourName
   Repo: github.com/yourname/pixel-reveal
========================================================= */

(function () {

  "use strict";

  /* ======================
     CONFIG
  ====================== */

  const DEFAULTS = {
    grid: 12,
    duration: 0.3,
    stagger: 0.005,
    start: "top 75%"
  };

  /* ======================
     INIT GSAP
  ====================== */

  if (typeof gsap === "undefined") {
    console.warn("PixelReveal: GSAP not found");
    return;
  }

  if (typeof ScrollTrigger !== "undefined") {
    gsap.registerPlugin(ScrollTrigger);
  }

  /* ======================
     UTILITIES
  ====================== */

  function createWrapper(img) {

    const wrapper = document.createElement("div");
    wrapper.className = "image_wrapper";

    img.parentNode.insertBefore(wrapper, img);
    wrapper.appendChild(img);

    return wrapper;
  }

  function createContent(img) {

    const content = document.createElement("div");

    content.className = "pixel_content";
    content.textContent = img.dataset.text || "";

    content.style.color =
      img.dataset.textColor || "#fff";

    return content;
  }

  function createGrid(img, gridSize) {

    const grid = document.createElement("div");

    grid.className = "pixel_grid";

    grid.style.setProperty(
      "--pixel-color",
      img.dataset.color || "#fff"
    );

    grid.style.gridTemplateColumns =
      `repeat(${gridSize}, 1fr)`;

    grid.style.gridTemplateRows =
      `repeat(${gridSize}, 1fr)`;

    const total = gridSize * gridSize;

    for (let i = 0; i < total; i++) {
      grid.appendChild(document.createElement("div"));
    }

    return grid;
  }

  function createTimeline(pixels, duration) {

    return gsap.timeline({ paused: true })
      .to(pixels, {
        opacity: 0,
        duration,
        stagger: {
          each: DEFAULTS.stagger,
          from: "random"
        },
        ease: "power2.out"
      });

  }

  /* ======================
     MODES
  ====================== */

  function setupHover(wrapper, content, pixels, tl) {

    wrapper.addEventListener("mouseenter", () => {

      gsap.to(content, {
        opacity: 0,
        duration: 0.2
      });

      tl.restart();

    });

    wrapper.addEventListener("mouseleave", () => {

      tl.pause(0);

      gsap.set(pixels, {
        opacity: 1
      });

      gsap.to(content, {
        opacity: 1,
        duration: 0.2
      });

    });

  }

  function setupScroll(wrapper, content, tl) {

    if (typeof ScrollTrigger === "undefined") {
      tl.play();
      return;
    }

    ScrollTrigger.create({

      trigger: wrapper,
      start: DEFAULTS.start,
      once: true,

      onEnter: () => {

        gsap.to(content, {
          opacity: 0,
          duration: 0.3
        });

        tl.play();

      }

    });

  }

  /* ======================
     MAIN INIT
  ====================== */

  function initImage(img) {

    const gridSize =
      Math.max(
        1,
        parseInt(img.dataset.grid) || DEFAULTS.grid
      );

    const duration =
      parseFloat(img.dataset.duration)
      || DEFAULTS.duration;

    const isHover =
      img.hasAttribute("data-hover");

    const wrapper = createWrapper(img);

    const content = createContent(img);
    wrapper.appendChild(content);

    const grid = createGrid(img, gridSize);
    wrapper.appendChild(grid);

    const pixels =
      Array.from(grid.children);

    const tl =
      createTimeline(pixels, duration);

    if (isHover)
      setupHover(wrapper, content, pixels, tl);
    else
      setupScroll(wrapper, content, tl);

  }

  function initAll() {

    document
      .querySelectorAll("img[data-pixel]")
      .forEach(initImage);

  }

  /* ======================
     AUTO INIT
  ====================== */

  if (document.readyState === "loading") {

    document.addEventListener(
      "DOMContentLoaded",
      initAll
    );

  } else {

    initAll();

  }

})();
